 32	  const trigger = useRef<HTMLButtonElement>(null);
 33	  useEffect(() => {
 34	    if (!open) return;
 35	    const outside = (event: PointerEvent) => {if (!root.current?.contains(event.target as Node)) setOpen(false);};
 36	    document.addEventListener('pointerdown', outside);
 37	    return () => document.removeEventListener('pointerdown', outside);
 38	  }, [open]);
 39	  return <div ref={root} style={{position:'relative', display:'inline-block'}} onMouseEnter={() => {if (openOnHover) setOpen(true);}}
 40	    onBlur={event => {if (!event.currentTarget.contains(event.relatedTarget as Node)) setOpen(false);}}
 41	    onKeyDown={event => {if (event.key === 'Escape') {setOpen(false); trigger.current?.focus(); event.stopPropagation();}}}>
 42	    <button ref={trigger} type="button" aria-expanded={open} aria-controls={id} onClick={() => setOpen(true)}>{label}</button>
 43	    <div id={id} hidden={!open} style={{position:'absolute', top:'100%', left:0, zIndex:10, background:'Canvas', color:'CanvasText'}}
 44	      onClick={event => {
 45	        const action=(event.target as Element).closest('button:not(:disabled), a[href]');
 46	        if (action && event.currentTarget.contains(action)) {setOpen(false); trigger.current?.focus();}
 47	      }}>{open && children}</div>
 48	  </div>;
