 53	export function AsyncActionMenu<T>({label, items, openOnHover, pendingContent, errorContent}: {
 54	  label: string; openOnHover?: boolean; pendingContent?: React.ReactNode;
 55	  errorContent: (error: unknown) => React.ReactNode;
 56	  items: {id?: string; name: string; disabled?: boolean;
 57	    onAction: () => Promise<AsyncResult<T>>; onApplied?: (data: T) => void}[];
 58	}) {
 59	  const action = useAsyncAction();
 60	  return <div>
 61	    <ActionMenu label={label} openOnHover={openOnHover}>
 62	      {items.map((item, index)=><ActionButton key={item.id ?? index}
 63	        disabled={item.disabled || action.pending} aria-busy={action.pending}
 64	        onClick={()=>{void action.run(item.onAction, item.onApplied);}}>
 65	        {item.name}</ActionButton>)}
 66	    </ActionMenu>
 67	    {action.pending && pendingContent && <span role="status">{pendingContent}</span>}
 68	    {action.failed && <span role="alert">{errorContent(action.error)}</span>}
