 73	export function Menu({label, items}: {label: string; items: {name: string; disabled?: boolean; onSelect: () => void}[]}) {
 74	  const [open,setOpen]=useState(false), root=useRef<HTMLDivElement>(null), trigger=useRef<HTMLButtonElement>(null);
 75	  const panel=useRef<HTMLDivElement>(null), initial=useRef(0), id=useId();
 76	  const available=()=>Array.from(panel.current?.querySelectorAll<HTMLButtonElement>('button:not(:disabled)')??[]);
 77	  const close=(focus=false)=>{setOpen(false);if(focus)trigger.current?.focus();};
 78	  useEffect(()=>{
 79	    if(!open)return;
 80	    const buttons=available();buttons[initial.current<0?buttons.length-1:0]?.focus();
 81	    const outside=(event:PointerEvent)=>{if(!root.current?.contains(event.target as Node))close();};
 82	    document.addEventListener('pointerdown',outside);
 83	    return()=>document.removeEventListener('pointerdown',outside);
 84	  },[open]);
 85	  const show=(last=false)=>{initial.current=last?-1:0;setOpen(true);};
 86	  return <div ref={root} style={{position:'relative',display:'inline-block'}}
 87	    onBlur={event=>{if(!event.currentTarget.contains(event.relatedTarget as Node))close();}}>
 88	    <button ref={trigger} type="button" aria-haspopup="menu" aria-expanded={open} aria-controls={id}
 89	      onClick={()=>open?close():show()} onKeyDown={event=>{
 90	        if(event.key==='ArrowDown'||event.key==='ArrowUp'){event.preventDefault();show(event.key==='ArrowUp');}
 91	      }}>{label}</button>
 92	    {open&&<div id={id} ref={panel} role="menu" aria-label={label}
 93	      style={{position:'absolute',zIndex:10,background:'Canvas',color:'CanvasText'}} onKeyDown={event=>{
 94	        const buttons=available(), index=buttons.indexOf(document.activeElement as HTMLButtonElement);
 95	        if(event.key==='Escape'){event.preventDefault();event.stopPropagation();close(true);return;}
 96	        if(event.key==='Tab'){close();return;}
 97	        if(!buttons.length)return;
 98	        const next=event.key==='Home'?0:event.key==='End'?buttons.length-1:
 99	          event.key==='ArrowDown'?(index+1)%buttons.length:event.key==='ArrowUp'?(index-1+buttons.length)%buttons.length:-1;
100	        if(next>=0){event.preventDefault();buttons[next].focus();}
101	        else if(event.key.length===1&&!event.ctrlKey&&!event.metaKey&&!event.altKey){
102	          const ordered=[...buttons.slice(index+1),...buttons.slice(0,index+1)];
103	          const match=ordered.find(b=>b.textContent?.toLocaleLowerCase().startsWith(event.key.toLocaleLowerCase()));
104	          if(match){event.preventDefault();match.focus();}
105	        }
106	      }}>{items.map((item,index)=><button key={index} type="button" role="menuitem" tabIndex={-1}
