118	export function AsyncCheckbox({label, checked, onCommit, onError, disabled, id, ...props}:
119	  Omit<React.InputHTMLAttributes<HTMLInputElement>, 'type' | 'checked' | 'defaultChecked' | 'onChange' | 'onError'> &
120	  {label: string; checked: boolean; onCommit: (checked: boolean) => Promise<unknown>; onError?: (error: unknown) => void}) {
121	  const generated = useId(), inputId = id ?? generated;
122	  const [value, setValue] = useState(checked), [pending, setPending] = useState(false);
123	  const mounted = useRef(true), inFlight = useRef(false);
124	  useEffect(() => {mounted.current = true; return () => {mounted.current = false;};}, []);
125	  useEffect(() => {setValue(checked);}, [checked]);
126	  const change = async (next: boolean) => {
127	    if (inFlight.current) return;
128	    const previous = value;
129	    inFlight.current = true; setValue(next); setPending(true);
130	    try {await onCommit(next);}
131	    catch (error) {if (mounted.current) {setValue(previous); onError?.(error);}}
132	    finally {inFlight.current = false; if (mounted.current) setPending(false);}
133	  };
134	  return <label htmlFor={inputId}><input {...props} id={inputId} type="checkbox" checked={value}
135	    disabled={disabled || pending} aria-busy={pending} onChange={event => void change(event.target.checked)}/>{label}</label>;
136	}
