140	  useEffect(() => {
141	    const dialog = ref.current;
142	    if (!dialog) return;
143	    if (open && !dialog.open) dialog.showModal();
144	    if (!open && dialog.open) dialog.close();
145	    return () => {if (dialog.open) dialog.close();};
146	  }, [open]);
147	  return <dialog ref={ref} aria-label={name} onCancel={event => {event.preventDefault(); onClose();}}
148	    onClose={event => {if (open && !event.currentTarget.open) onClose();}}>{children}</dialog>;
